SELECT     REPORT_DATE,     SHIPMENT_NO,     SHIPMENT_STATUS,     CASE SHIPMENT_STATUS         WHEN 'I' THEN 'In Progress'         WHEN 'R' THEN 'Received'         WHEN 'C' THEN 'Closed'         WHEN 'D' THEN 'Deleted'         ELSE SHIPMENT_STATUS     END                                                   AS SHIPMENT_STATUS_DESC,     ASN_NUMBER,     SHIP_DATE,     RECEIVE_DATE,     TRUNC(SYSDATE) - TRUNC(RECEIVE_DATE)                 AS DAYS_SINCE_RECEIPT,     INVC_MATCH_STATUS,     CASE INVC_MATCH_STATUS         WHEN 'U' THEN 'Unmatched'         WHEN 'M' THEN 'Matched'         WHEN 'C' THEN 'Closed'         ELSE NVL(INVC_MATCH_STATUS, 'Not Set')     END                                                   AS INVC_MATCH_STATUS_DESC,     PO_NUMBER,     PO_STATUS,     CASE PO_STATUS         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE PO_STATUS     END                                                   AS PO_STATUS_DESC,     SUPPLIER_ID,     SUPPLIER_NAME,     SUPPLIER_STATUS,     LOCATION_ID,     LOC_TYPE,     CASE LOC_TYPE         WHEN 'S' THEN STORE_NAME         WHEN 'W' THEN WH_NAME         ELSE TO_CHAR(LOCATION_ID)     END                                                   AS LOCATION_NAME,     DEPT_NO,     DEPT_NAME,     CLASS_NO,     CLASS_NAME,     SUBCLASS_NO,     SUBCLASS_NAME,     ITEM_ID,     ITEM_DESCRIPTION,     UOM,     PACK_IND,     CATCH_WEIGHT_IND,     CASE CATCH_WEIGHT_IND         WHEN 'Y' THEN 'CATCH WEIGHT - Shortage qty is in weight terms'         ELSE          'STANDARD ITEM - Shortage qty is in standard UOM'     END                                                   AS CATCH_WEIGHT_DESC,     QTY_ORDERED,     QTY_EXPECTED,     QTY_RECEIVED,     QTY_EXPECTED - QTY_RECEIVED                          AS QTY_SHORTAGE,     CASE WHEN QTY_EXPECTED &gt; 0          THEN ROUND((QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED * 100, 2)     END                                                   AS SHORTAGE_PCT,     ROUND(SHORTAGE_COST_RAW, 2)                          AS SHORTAGE_COST_VALUE,     ROUND(ACCEPTED_COST_RAW, 2)                          AS ACCEPTED_COST_VALUE,     ROUND(TOTAL_ORDERED_COST_RAW, 2)                     AS TOTAL_ORDERED_COST,     FREIGHT_EXP_VALUE,     CASE         WHEN FREIGHT_EXP_VALUE = 0         THEN 'ZERO FREIGHT - No freight charges on this line'         WHEN FREIGHT_EXP_VALUE &gt; 0         THEN 'FREIGHT APPLIED'         ELSE 'FREIGHT NOT APPLICABLE'     END                                                   AS FREIGHT_STATUS,     CURRENT_SOH,     ROUND(CURRENT_SOH * NVL(WAC, 0), 2)                  AS CURRENT_SOH_COST_VALUE,     INVC_XREF_ID,     LINKED_INVOICE_ID,     INVOICE_AMOUNT,     INVOICE_DATE,     CASE         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 1.00         THEN '1 - FULL SHORTAGE: 100 Percent of delivery short'         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 0.50         THEN '2 - HIGH: 50 to 100 Percent short'         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 0.20         THEN '3 - MEDIUM: 20 to 50 Percent short'         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) &gt; 0         THEN '4 - LOW: Under 20 Percent short'         ELSE '5 - REVIEW'     END                                                   AS SHORTAGE_SEVERITY,     CASE         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 1.00         THEN 'Full shortage: Create RTV for full shipment; raise supplier debit note via ReIM'         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 0.50         THEN 'High shortage: Create RTV for short qty; reorder replacement via replenishment or manual PO'         WHEN QTY_EXPECTED &gt; 0              AND (QTY_EXPECTED - QTY_RECEIVED) / QTY_EXPECTED &gt;= 0.20         THEN 'Medium shortage: Create RTV