  NVL(ol.QTY_ORDERED,   0)                          AS QTY_ORDERED,         NVL(ss.QTY_EXPECTED,  0)                          AS QTY_EXPECTED,         NVL(ss.QTY_RECEIVED,  0)                          AS QTY_RECEIVED,         NVL(ss.UNIT_COST,     0)                          AS UNIT_COST,         (NVL(ss.QTY_EXPECTED, 0)          - NVL(ss.QTY_RECEIVED, 0)) * NVL(ss.UNIT_COST, 0)                                                           AS SHORTAGE_COST_RAW,         NVL(ss.QTY_RECEIVED, 0) * NVL(ss.UNIT_COST, 0)   AS ACCEPTED_COST_RAW,         NVL(ol.QTY_ORDERED,  0) * NVL(ss.UNIT_COST, 0)   AS TOTAL_ORDERED_COST_RAW,         NVL(ole.EST_EXP_VALUE, 0)                         AS FREIGHT_EXP_VALUE,         NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH,         NVL(ils.AV_COST,       0)                         AS WAC,         ix.ID                                             AS INVC_XREF_ID,         ih.INVC_ID                                        AS LINKED_INVOICE_ID,         ih.TOTAL_MERCH_COST                               AS INVOICE_AMOUNT,         ih.INVC_DATE                                      AS INVOICE_DATE     FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU              ss   ON  sh.SHIPMENT  = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO  = oh.ORDER_NO     LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC           ol   ON  oh.ORDER_NO  = ol.ORDER_NO                                                     AND  ss.ITEM      = ol.ITEM                                                     AND  sh.TO_LOC    = ol.LOCATION     JOIN (

