:[\"CURRENT_SOH_COST_VALUE\"],\"expressionSourceColumns\":[\"CURRENT_SOH_COST_VALUE\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"CURRENT_SOH_COST_VALUE\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"CURRENT_SOH_COST_VALUE\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"6\"},{\"id\":\"8\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"PO_NUMBER\"],\"expressionSourceColumns\":[\"PO_NUMBER\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"PO_NUMBER\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"PO_NUMBER\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"7\"},{\"id\":\"9\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"LOCATION_ID\"],\"expressionSourceColumns\":[\"LOCATION_ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"LOCATION_ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"LOCATION_ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"8\"},{\"id\":\"10\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"SUPPLIER_ID\"],\"expressionSourceColumns\":[\"SUPPLIER_ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"SUPPLIER_ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"SUPPLIER_ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"9\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 5 ────────────────────────────────────────────────────────────
SELECT\\n        TRUNC(SYSDATE)                                    AS REPORT_DATE,\\n        sh.SHIPMENT                                       AS SHIPMENT_NO,\\n        sh.STATUS_CODE                                    AS SHIPMENT_STATUS,\\n        sh.ASN                                            AS ASN_NUMBER,\\n        sh.SHIP_DATE                                      AS SHIP_DATE,\\n        sh.RECEIVE_DATE                                   AS RECEIVE_DATE,\\n        sh.INVC_MATCH_STATUS                              AS INVC_MATCH_STATUS,\\n        sh.ORDER_NO                                       AS PO_NUMBER,\\n        oh.STATUS                                         AS PO_STATUS,\\n        oh.SUPPLIER                                       AS SUPPLIER_ID,\\n        sp.SUP_NAME                                       AS SUPPLIER_NAME,\\n        sp.SUP_STATUS                                     AS SUPPLIER_STATUS,\\n        sh.TO_LOC                                         AS LOCATION_ID,\\n        sh.TO_LOC_TYPE                                    AS LOC_TYPE,\\n        st.STORE_NAME                                     AS STORE_NAME,\\n        wh.WH_NAME                                        AS WH_NAME,\\n        im.DEPT                                           AS DEPT_NO,\\n        d.DEPT_NAME                                       AS DEPT_NAME,\\n        im.CLASS                                          AS CLASS_NO,\\n        c.CLASS_NAME                                      AS CLASS_NAME,\\n        im.SUBCLASS                                       AS SUBCLASS_NO,\\n        sc.SUB_NAME                                       AS SUBCLASS_NAME,\\n        ss.ITEM                                           AS ITEM_ID,\\n        im.ITEM_DESC                                      AS ITEM_DESCRIPTION,\\n        im.STANDARD_UOM                                   AS UOM,\\n        im.PACK_IND                                       AS PACK_IND,\\n        im.CATCH_WEIGHT_IND                               AS CATCH_WEIGHT_IND,\\n        NVL(ol.QTY_ORDERED,   0)                          AS QTY_ORDERED,\\n        NVL(ss.QTY_EXPECTED,  0)                          AS QTY_EXPECTED,\\n        NVL(ss.QTY_RECEIVED,  0)                          AS QTY_RECEIVED,\\n        NVL(ss.UNIT_COST,     0)                          AS UNIT_COST,\\n        (NVL(ss.QTY_EXPECTED, 0)\\n         - NVL(ss.QTY_RECEIVED, 0)) * NVL(ss.UNIT_COST, 0)\\n                                                          AS SHORTAGE_COST_RAW,\\n        NVL(ss.QTY_RECEIVED, 0) * NVL(ss.UNIT_COST, 0)   AS ACCEPTED_COST_RAW,\\n        NVL(ol.QTY_ORDERED,  0) * NVL(ss.UNIT_COST, 0)   AS TOTAL_ORDERED_COST_RAW,\\n        NVL(ole.EST_EXP_VALUE, 0)                         AS FREIGHT_EXP_VALUE,\\n        NVL(ils.STOCK_ON_HAND, 0)                         AS CURRENT_SOH,\\n        NVL(ils.AV_COST,       0)                         AS WAC,\\n        ix.ID                                             AS INVC_XREF_ID,\\n        ih.INVC_ID                                        AS LINKED_INVOICE_ID,\\n        ih.TOTAL_MERCH_COST                               AS INVOICE_AMOUNT,\\n        ih.INVC_DATE                                      AS INVOICE_DATE\\n    FROM  MFCS_RDS.RDS_WV_SHIPMENT             sh\\n    JOIN  MFCS_RDS.RDS_WV_SHIPSKU              ss   ON  sh.SHIPMENT  = ss.SHIPMENT\\n    JOIN  MFCS_RDS.RDS_WV_ORDHEAD              oh   ON  sh.ORDER_NO  = oh.ORDER_NO\\n    LEFT JOIN MFCS_RDS.RDS_WV_ORDLOC           ol   ON  oh.ORDER_NO  = ol.ORDER_NO\\n                                                    AND  ss.ITEM      = ol.ITEM\\n                                                    AND  sh.TO_LOC    = ol.LOCATION\\n    JOIN (\\n

-- ── Query 6 ────────────────────────────────────────────────────────────
SELECT ITEM, ITEM_DESC, DEPT, CLASS, SUBCLASS,\\n               STATUS, STANDARD_UOM, PACK_IND, CATCH_WEIGHT_IND\\n        FROM   MFCS_RDS.RDS_WV_ITEM_MASTER\\n        WHERE  TRAN_LEVEL = ITEM_LEVEL\\n    )                                          im   ON  ss.ITEM      = im.ITEM\\n    JOIN  MFCS_RDS.RDS_WV_DEPS                 d    ON  im.DEPT      = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS                c    ON  im.DEPT      = c.DEPT\\n                                                    AND  im.CLASS     = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS             sc   ON  im.DEPT      = sc.DEPT\\n                                                    AND  im.CLASS     = sc.CLASS\\n                                                    AND  im.SUBCLASS  = sc.SUBCLASS\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS             sp   ON  oh.SUPPLIER  = sp.SUPPLIER\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE            st   ON  sh.TO_LOC    = st.STORE\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH               wh   ON  sh.TO_LOC    = wh.WH\\n    LEFT JOIN (\\n

-- ── Query 7 ────────────────────────────────────────────────────────────
SELECT ORDER_NO, ITEM, LOCATION, SUM(NVL(EST_EXP_VALUE,0)) AS EST_EXP_VALUE\\n        FROM   MFCS_RDS.RDS_WV_ORDLOC_EXP\\n        GROUP BY ORDER_NO, ITEM, LOCATION\\n    )                                          ole  ON  oh.ORDER_NO  = ole.ORDER_NO\\n                                                    AND  ss.ITEM      = ole.ITEM\\n                                                    AND  sh.TO_LOC    = ole.LOCATION\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH     ils  ON  ss.ITEM      = ils.ITEM\\n                                                    AND  sh.TO_LOC    = ils.LOC\\n                                                    AND  sh.TO_LOC_TYPE = ils.LOC_TYPE\\n    LEFT JOIN MFCS_RDS.RDS_WV_INVC_XREF        ix   ON  sh.SHIPMENT  = ix.SHIPMENT\\n    LEFT JOIN MFCS_RDS.RDS_WV_INVC_HEAD        ih   ON  ix.INVC_ID   = ih.INVC_ID\\n    WHERE\\n        NVL(ss.QTY_EXPECTED, 0) &gt; NVL(ss.QTY_RECEIVED, 0)\\n        AND sh.RECEIVE_DATE &gt;= ADD_MONTHS(SYSDATE, -3)\\n)\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-08-03T05:26:39.444+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_202_Fresh_Reject_Freight'","parent-namespace":"ReCommon","parent-name":"RPT_202_Fresh_Reject_Freight","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_202_Fresh_Reject_Freight'"}
